svg.script:
(function () {
  'use strict';
  const ns = 'http://www.w3.org/2000/svg';
  const xlink = 'http://www.w3.org/1999/xlink';
  const svg = document.documentElement;
  const itemLayer = document.getElementById('market-crate-contents');
  let collectedCount = location.hash === '#filled' ? 1 : 0;
  let nextId = 0;

  // Exactly zero items => floor shown. One or more => hollow frame shown.
  function setCount(value) {
    const n = Math.max(0, Math.floor(Number(value) || 0));
    collectedCount = n;
    svg.setAttribute('data-state', n ? 'filled' : 'empty');
    svg.setAttribute('data-count', String(n));
    return n;
  }

  function clear() {
    itemLayer.replaceChildren();
    return setCount(0);
  }

  // To draw the collected ingredients inside the crate, use addItem(imageSrc).
  // For custom placement, use addItem(imageSrc, {x, y, width, height, rotation}).
  // Items sit BEHIND the slats, visible through the hollow interior and gaps.
  function addItem(imageSrc, options) {
    const src = (typeof imageSrc === 'string') ? imageSrc : imageSrc && (imageSrc.src || imageSrc.href);
    if (!src || typeof src !== 'string') return null;
    const cfg = options || (typeof imageSrc === 'object' ? imageSrc : {}) || {};
    const index = itemLayer.children.length;
    const width = positive(cfg.width, 138);
    const height = positive(cfg.height, width);
    const x = finite(cfg.x, 420 + (index * 103) % 355);
    const y = finite(cfg.y, 435 - Math.min(140, Math.floor(index / 5) * 36) + (index % 3) * 19);
    const rotation = finite(cfg.rotation, (index % 5 - 2) * 8);
    const item = document.createElementNS(ns, 'image');
    const id = 'market-item-' + (++nextId);
    item.setAttribute('id', id);
    item.setAttribute('x', String(x));
    item.setAttribute('y', String(y));
    item.setAttribute('width', String(width));
    item.setAttribute('height', String(height));
    item.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    item.setAttribute('transform', 'rotate(' + rotation + ' ' + (x + width / 2) + ' ' + (y + height / 2) + ')');
    item.setAttributeNS(xlink, 'href', src);
    itemLayer.appendChild(item);
    setCount(Math.max(collectedCount + 1, itemLayer.children.length));
    return id;
  }

  function removeItem(itemId) {
    if (itemId) {
      for (const child of Array.from(itemLayer.children)) {
        if (child.id === itemId) { child.remove(); break; }
      }
    } else if (itemLayer.lastElementChild) {
      itemLayer.lastElementChild.remove();
    }
    return setCount(Math.max(0, collectedCount - 1, itemLayer.children.length));
  }

  function finite(v, defaultValue) { const n = Number(v); return Number.isFinite(n) ? n : defaultValue; }
  function positive(v, defaultValue) { const n = finite(v, defaultValue); return n > 0 ? n : defaultValue; }

  window.MarketCrate = Object.freeze({
    setCount, addItem, removeItem, clear, reset: clear,
    showFilled: function () { return setCount(Math.max(1, collectedCount)); },
    showEmpty: clear,
    getCount: function () { return collectedCount; },
    getState: function () { return collectedCount > 0 ? 'filled' : 'empty'; },
  });

  function handleMessage(data) {
    if (!data || typeof data !== 'object') return;
    switch (data.type) {
      case 'market_madness:crate_update':
      case 'market_madness:crate_count':
      case 'market-madness:crate-update':
        if (Array.isArray(data.items)) setCount(data.items.length);
        else setCount(data.count ?? data.itemCount ?? 0);
        break;
      case 'market_madness:crate_add':
        if (data.src || data.href) addItem(data.src || data.href, data);
        else setCount(collectedCount + 1);
        break;
      case 'market_madness:crate_remove':
        removeItem(data.id);
        break;
      case 'market_madness:crate_clear':
      case 'market_madness:crate_reset':
        clear();
        break;
    }
  }

  window.addEventListener('message', function (event) {
    // The crate does not read any private data; only honor messages from its parent.
    if (event.source === window.parent) handleMessage(event.data);
  });
  document.addEventListener('market_madness:crate_update', function (event) {
    handleMessage(Object.assign({ type: 'market_madness:crate_update' }, event.detail || {}));
  });
  document.addEventListener('market_madness:crate_add', function (event) {
    handleMessage(Object.assign({ type: 'market_madness:crate_add' }, event.detail || {}));
  });
  document.addEventListener('market_madness:crate_clear', function () { clear(); });

  // Observe changes when the host writes <image> elements directly into the content group.
  // This is useful when the host uses contentDocument rather than the addItem() method.
  new MutationObserver(function () {
    if (itemLayer.children.length && collectedCount === 0) setCount(itemLayer.children.length);
    else if (!itemLayer.children.length && collectedCount > 0 && svg.getAttribute('data-items-only') === 'true') setCount(0);
  }).observe(itemLayer, { childList: true });
})();
